import java.util.*;

public class Main {
    ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0, head);
        ListNode fast = dummy;
        ListNode slow = dummy;
        for (int i = 0; i < n; i++) {
            fast = fast.next;                                                       // advance fast n steps ahead first, establishing a fixed gap
        }
        while (fast.next != null) {
            fast = fast.next;                                                       // advance both pointers together, maintaining the same gap
            slow = slow.next;
        }
        slow.next = slow.next.next;                                                  // slow now sits exactly before the target; skip over it
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.removeNthFromEnd(head, 2);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

